CREATE TABLE "turma_carga_dia" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY (sequence name "turma_carga_dia_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"turma_id" integer NOT NULL,
	"data" date NOT NULL,
	"quantidade" integer NOT NULL,
	CONSTRAINT "pk_turma_carga_dia" PRIMARY KEY("id"),
	CONSTRAINT "uq_turma_carga_dia" UNIQUE("turma_id","data"),
	CONSTRAINT "ck_turma_carga_dia_quantidade" CHECK (quantidade >= 0)
);
