-- lote 3 (24/11/2026): a presença gravada em horas vira MINUTOS, sem perda (numeric(4,1):
-- 0,1 h = 6 min, sempre inteiro). Nenhuma frequência gravada é recalculada aqui.
UPDATE "turma_presenca" SET "quantidade" = round("horas" * 60)::integer;--> statement-breakpoint
-- a turma nasce com a unidade do treinamento (todas HORAS hoje)
UPDATE "turma" t SET "carga_unidade" = tr."carga_unidade" FROM "treinamento" tr WHERE tr."id" = t."treinamento_id";--> statement-breakpoint
-- a turma em horas de vários dias, com presença já lançada, cuja carga não se dividia por igual em
-- décimos (4,5 h em 2 dias: 2,3 + 2,2): guarda a divisão antiga como carga por dia, para a presença
-- lançada (138 min no 1º dia) não ficar acima do limite do dia da divisão nova (135 + 135).
INSERT INTO "turma_carga_dia" ("turma_id", "data", "quantidade")
SELECT x."id", g."dia"::date,
       ((x."decimos" / x."n") + CASE WHEN g."i" <= x."decimos" % x."n" THEN 1 ELSE 0 END) * 6
FROM (
  SELECT t."id", t."data_inicio", t."data_fim", (t."data_fim" - t."data_inicio" + 1) AS "n",
         round(coalesce(t."carga_horaria_horas", tr."carga_horaria_horas") * 10)::integer AS "decimos"
  FROM "turma" t JOIN "treinamento" tr ON tr."id" = t."treinamento_id"
  WHERE t."carga_unidade" = 'HORAS'
    AND EXISTS (SELECT 1 FROM "turma_presenca" p JOIN "inscricao" i ON i."id" = p."inscricao_id" WHERE i."turma_id" = t."id")
) x
CROSS JOIN LATERAL generate_series(x."data_inicio", x."data_fim", interval '1 day') WITH ORDINALITY AS g("dia", "i")
WHERE x."n" > 1 AND x."decimos" % x."n" <> 0;--> statement-breakpoint
